            move.w  #$8280,custom.DMACON ; DMACON: SET(0x8000) | DMAEN(0x0200) | COPEN(0x0080)
            clr.w   custom.COPJMP1      ; strobe COPJMP1 to activate
            rts
; End of subroutine: copper.start

