; ---- Subroutine: math.crc16_update ----
    ALIGN 2

math.crc16_update:
            lea     math.crc16_table,a0
            move.w  math.crc16_state,d1
            lsr.w   #8,d1           ; high byte of crc
            eor.b   d0,d1           ; table index
            move.w  math.crc16_state,d0
            lsl.w   #8,d0           ; crc <<= 8
            and.w   #$ff,d1
            add.w   d1,d1           ; word index
            move.w  (a0,d1.w),d1
            eor.w   d1,d0           ; new crc
            move.w  d0,math.crc16_state
            rts
; End of subroutine: math.crc16_update

; ---- Subroutine: math.crc16_end ----
; source: shared_m68k_math.p8:691

    ALIGN 2

math.crc16_end:
        ; loadm.w r605.w,[math.crc16_state]
    move.w  math.crc16_state,p8_regfile+1490
